// Get all incoming rows (past ideas for this platform)
const items = $input.all();

// Extract the idea text from each row
const texts = items.map(item => item.json.idea).filter(Boolean);

// Concatenate them so the agent can avoid repeating topics
const concatenated = texts.join(", ");

// Carry the platform id / brand voice forward so downstream nodes can use it
const platform = $('Get Platform').first().json;

return [{ json: { mergedText: concatenated, platform_id: platform.id, brand_voice_prompt: platform.brand_voice_prompt } }];

